@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--ink:#eef3e8;--muted:#92a49a;--acid:#c8f17b;--panel:rgba(9,24,21,.82);--line:rgba(216,236,215,.15)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#071310;color:var(--ink);font-family:Manrope,system-ui,sans-serif;touch-action:none;user-select:none;-webkit-user-select:none}.game-shell{position:relative;width:100%;height:100%;min-height:320px;overflow:hidden;background:#0b1c18}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 52%,transparent 34%,rgba(3,12,10,.16) 72%,rgba(3,10,9,.7) 130%),linear-gradient(180deg,rgba(5,16,14,.67),transparent 25%,transparent 65%,rgba(5,14,12,.55)}.topbar{position:absolute;z-index:2;top:max(22px,env(safe-area-inset-top));left:clamp(18px,3.8vw,56px);right:clamp(18px,3.8vw,56px);display:flex;align-items:center;justify-content:space-between;pointer-events:none}.brand{display:flex;align-items:center;gap:12px}.brand-mark{width:37px;height:37px;border:1px solid rgba(200,241,123,.5);border-radius:11px;color:var(--acid);display:grid;place-items:center;font-size:22px;background:rgba(12,30,24,.55);box-shadow:0 0 24px rgba(200,241,123,.08)}.brand strong{display:block;font-size:12px;letter-spacing:.15em;font-weight:800}.brand strong i{font-style:normal;color:var(--acid)}.eyebrow{font-family:'DM Mono',monospace;font-size:9px;letter-spacing:.16em;color:#9eb5a6;display:block;margin-bottom:4px}.icon-button{pointer-events:auto;border:1px solid var(--line);background:rgba(9,23,20,.62);color:#e2eadc;width:40px;height:40px;border-radius:12px;font-size:16px;cursor:pointer}.mission-card,.status-panel{z-index:2;position:absolute;background:linear-gradient(145deg,rgba(12,29,25,.89),rgba(8,21,19,.74));border:1px solid rgba(199,226,194,.17);backdrop-filter:blur(16px);box-shadow:0 18px 50px #02090655}.mission-card{top:105px;left:clamp(18px,3.8vw,56px);width:min(310px,calc(100vw - 36px));padding:16px 18px 14px;border-radius:15px}.mission-head{display:flex;align-items:center;gap:7px;color:#a8b8ac;font:9px 'DM Mono',monospace;letter-spacing:.1em}.live-dot{height:6px;width:6px;background:var(--acid);border-radius:100%;box-shadow:0 0 8px var(--acid)}.mission-step{margin-left:auto;color:var(--acid)}.mission-card h1{font-size:17px;margin:12px 0 5px;letter-spacing:-.03em}.mission-card p{color:#a7b7ab;font-size:11px;line-height:1.55;margin:0 0 13px}.objective-track{height:2px;background:#ffffff16;border-radius:2px}.objective-track span{height:100%;display:block;width:8%;background:var(--acid);box-shadow:0 0 9px #c8f17b88;transition:width .5s}.status-panel{top:105px;right:clamp(18px,3.8vw,56px);width:212px;padding:14px 15px;border-radius:14px}.status-line{display:flex;justify-content:space-between;padding-bottom:11px;border-bottom:1px solid var(--line);font:9px 'DM Mono',monospace;letter-spacing:.1em;color:#8da397}.status-line span:last-child{color:var(--acid);letter-spacing:0}.meter{display:grid;grid-template-columns:58px 1fr 22px;gap:8px;align-items:center;margin-top:12px;font:8px 'DM Mono',monospace;color:#9daf9f}.meter div{height:4px;background:#ffffff18;border-radius:5px;overflow:hidden}.meter i{height:100%;display:block;background:var(--acid);border-radius:5px;transition:width .3s}.meter b{font-weight:500;color:#e5eee2;text-align:right}.meter.focus i{background:#80d2bb}.inventory-row{margin-top:13px;border-top:1px solid var(--line);padding-top:10px;font:8px 'DM Mono',monospace;color:#9daf9f}.inventory-row div{margin-top:7px;display:flex;gap:5px;flex-wrap:wrap}.item-chip{padding:4px 7px;border-radius:5px;background:#c8f17b15;color:#d4efa6;border:1px solid #c8f17b26;font-size:8px}.zone-label{position:absolute;left:clamp(18px,3.8vw,56px);bottom:33px;z-index:2;display:flex;align-items:center;gap:10px;text-shadow:0 1px 5px #07110e}.zone-icon{font-size:21px;color:var(--acid)}.zone-label b{display:block;font-size:11px;font-weight:600}.zone-label small{display:block;color:#9aaca1;font:9px 'DM Mono',monospace;margin-top:3px}.bottom-note{position:absolute;right:clamp(18px,3.8vw,56px);bottom:36px;color:#84978b;font:8px 'DM Mono',monospace;letter-spacing:.11em;z-index:2}.bottom-note span{color:var(--acid);margin-right:5px}.controls-hint{position:absolute;z-index:2;left:50%;bottom:32px;transform:translateX(-50%);border:1px solid #e6f4e61f;background:#091915c9;color:#a7b9ac;padding:9px 13px;border-radius:9px;font-size:9px;white-space:nowrap;backdrop-filter:blur(10px)}.hint-key{display:inline-grid;place-items:center;min-width:20px;height:18px;padding:0 5px;margin:0 2px;background:#d7e6d812;border:1px solid #d7e6d827;border-radius:4px;color:#e8f0e2;font:9px 'DM Mono',monospace}.hint-divider{padding:0 7px;color:#62776b}.interaction{position:absolute;z-index:5;left:50%;bottom:74px;transform:translate(-50%,18px);width:min(380px,calc(100vw - 28px));padding:17px;border-radius:16px;border:1px solid #d9e8d92c;background:linear-gradient(145deg,rgba(11,28,24,.97),rgba(7,18,16,.97));box-shadow:0 22px 80px #020806bf;opacity:0;pointer-events:none;transition:opacity .2s,transform .2s;backdrop-filter:blur(20px)}.interaction.open{opacity:1;pointer-events:auto;transform:translate(-50%,0)}.interaction-top{display:flex;justify-content:space-between;align-items:start}.interaction h2{margin:2px 0 0;font-size:19px;letter-spacing:-.04em}.close-button{width:28px;height:28px;border:1px solid var(--line);border-radius:8px;background:#ffffff09;color:#cad9cc;font-size:20px;line-height:1;cursor:pointer}.interaction p{margin:10px 0 12px;color:#a6b6aa;font-size:11px;line-height:1.55}.choices{display:grid;gap:7px}.choice{width:100%;display:flex;align-items:center;justify-content:space-between;text-align:left;gap:8px;padding:11px 12px;border:1px solid #dce8dc20;background:#ffffff08;color:#e5eee3;border-radius:9px;font:600 11px Manrope,sans-serif;cursor:pointer;transition:background .15s,border .15s}.choice:hover,.choice:active{border-color:#c8f17b70;background:#c8f17b10}.choice span{color:var(--acid);font:14px 'DM Mono',monospace}.choice small{display:block;color:#99aa9e;font-weight:400;font-size:9px;margin-top:3px}.choice.primary{background:#c8f17b;color:#142016;border-color:#c8f17b;justify-content:center;letter-spacing:.08em}.choice.primary span{color:#253d24}.toast{position:absolute;z-index:8;left:50%;top:50%;transform:translate(-50%,14px);padding:10px 14px;border:1px solid #dcead92b;border-radius:10px;background:#0b1b16ed;color:#dfebdb;font-size:11px;opacity:0;pointer-events:none;transition:.2s;white-space:nowrap;box-shadow:0 8px 30px #0005}.toast.show{opacity:1;transform:translate(-50%,0)}.mobile-controls{display:none;position:absolute;z-index:3;left:16px;right:16px;bottom:max(28px,env(safe-area-inset-bottom));align-items:end;justify-content:space-between;pointer-events:none}.dpad{width:124px;height:116px;position:relative;pointer-events:auto}.pad{position:absolute;width:40px;height:40px;border:1px solid #e0efdf3b;border-radius:12px;background:rgba(13,31,26,.76);color:#ecf4e9;font-size:23px;box-shadow:0 5px 16px #0004;touch-action:none}.pad:active{background:#c8f17b33;border-color:#c8f17b}.pad.up{left:42px;top:0}.pad.left{left:0;top:39px}.pad.down{left:42px;top:76px}.pad.right{right:0;top:39px}.act-button{pointer-events:auto;width:69px;height:69px;border-radius:50%;border:1px solid #c8f17b9c;background:rgba(15,35,27,.83);color:var(--acid);box-shadow:0 0 28px #c8f17b1c;display:grid;place-items:center;align-content:center;gap:1px}.act-button span{font-size:23px}.act-button small{font:7px 'DM Mono',monospace;letter-spacing:.07em;color:#d3e2cf}.ending{position:absolute;inset:0;z-index:10;display:grid;place-items:center;background:#06110fd9;backdrop-filter:blur(12px);opacity:0;pointer-events:none;transition:opacity .4s}.ending.open{opacity:1;pointer-events:auto}.ending-card{width:min(420px,calc(100vw - 36px));padding:28px;border:1px solid #dcebd82c;border-radius:18px;background:linear-gradient(145deg,#10251e,#091713);box-shadow:0 25px 100px #0009}.ending-card h2{font-size:26px;margin:14px 0 9px;letter-spacing:-.04em}.ending-card p{color:#a9baaa;font-size:12px;line-height:1.7}.ending-stats{display:flex;gap:8px;margin:18px 0}.ending-stats span{flex:1;padding:10px;background:#ffffff08;border:1px solid var(--line);border-radius:8px;color:#9db0a1;font:9px 'DM Mono',monospace}.ending-stats b{display:block;color:var(--acid);font-size:15px;margin-top:4px}
@media(max-width:760px){.topbar{top:max(13px,env(safe-area-inset-top));left:16px;right:16px}.brand-mark{width:32px;height:32px}.brand strong{font-size:10px}.brand .eyebrow{font-size:7px}.icon-button{width:35px;height:35px}.mission-card{top:62px;left:14px;width:min(250px,calc(100vw - 28px));padding:11px 12px;border-radius:12px}.mission-card h1{font-size:14px;margin:7px 0 3px}.mission-card p{font-size:9px;line-height:1.4;margin-bottom:9px}.mission-head{font-size:7px}.status-panel{top:62px;right:14px;width:143px;padding:10px;border-radius:12px}.status-line{font-size:7px;padding-bottom:7px}.meter{grid-template-columns:44px 1fr 18px;gap:5px;margin-top:9px;font-size:7px}.inventory-row{font-size:7px;margin-top:9px;padding-top:7px}.item-chip{font-size:7px;padding:3px 5px}.zone-label{left:15px;bottom:158px;gap:7px}.zone-label b{font-size:9px}.zone-label small{font-size:8px}.zone-icon{font-size:17px}.mobile-controls{display:flex}.bottom-note{display:none}.controls-hint{bottom:132px;font-size:8px;padding:7px 10px}.hint-key{height:16px;font-size:8px}.interaction{bottom:145px;width:min(380px,calc(100vw - 24px));padding:14px;max-height:54vh;overflow:auto}.interaction h2{font-size:17px}.interaction p{font-size:10px;margin:7px 0 10px}.choice{padding:10px;font-size:10px}.choice small{font-size:8px}.toast{top:55%;font-size:10px}.ending-card{padding:22px}}
@media(max-height:500px) and (orientation:landscape){.mission-card{top:62px;width:245px}.status-panel{top:62px}.zone-label{bottom:16px}.controls-hint{bottom:14px}.mobile-controls{bottom:9px}.dpad{transform:scale(.8);transform-origin:bottom left}.act-button{width:58px;height:58px}.interaction{bottom:68px;max-height:76vh}.bottom-note{bottom:17px}}

(() => {
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const $=id=>document.getElementById(id);
const W=14,H=14,TAU=Math.PI*2;
let cw=innerWidth,ch=innerHeight,dpr=1,tileW=58,tileH=29,cam={x:0,y:0};
let keys={},held={x:0,y:0},lastFrame=0,toastTimer=0,nearTarget=null,interactTarget=null,walkTarget=null;
const initial={hp:100,focus:3,core:false,medkit:false,power:true,terminal:false,lights:true,guardStun:0,guardDistracted:0,alarm:0,noise:0,escaped:false,steps:0,choices:0,crateMoved:false,plantHarvested:false,logs:false,exitOpen:false};
let state={...initial};
const player={x:2.1,y:10.1,face:1,walk:0,anim:0};
const props=[
 {id:'power',x:3,y:3,name:'Распределительный щит',type:'ЭНЕРГОУЗЕЛ',desc:'Потрескивающий щит держит оранжерею под напряжением. На крышке наклейка: «не отключать при цветении».',kind:'panel',blocking:true},
 {id:'terminal',x:9,y:3,name:'Архивный терминал',type:'ТЕРМИНАЛ',desc:'Стекло запотело изнутри. В журнале наверняка есть запись о ядре памяти.',kind:'terminal',blocking:true},
 {id:'core',x:10,y:5,name:'Ядро памяти',type:'ЦЕЛЬ ОПЕРАЦИИ',desc:'Стеклянная капсула пульсирует тусклым зелёным. Внутри — последние воспоминания станции.',kind:'core',blocking:true},
 {id:'plant',x:6,y:8,name:'Лунная орхидея',type:'ЖИВОЙ ОБЪЕКТ',desc:'Редкое растение раскрывает лепестки в темноте. Пыльца щекочет нос — может быть, она действует на охранного дрона.',kind:'plant',blocking:true},
 {id:'crate',x:5,y:6,name:'Транспортный контейнер',type:'ПЕРЕМЕЩАЕМЫЙ ОБЪЕКТ',desc:'Тяжёлый ящик перекрывает узкий проход. За ним что-то поблёскивает.',kind:'crate',blocking:true},
 {id:'locker',x:2,y:7,name:'Аптечный шкафчик',type:'КОНТЕЙНЕР',desc:'Дверца заперта на простой магнитный замок. Внутри может быть аптечка.',kind:'locker',blocking:true},
 {id:'radio',x:4,y:10,name:'Садовый динамик',type:'ОКРУЖЕНИЕ',desc:'Старый динамик подключён к системе оповещения. Он ещё работает.',kind:'radio',blocking:true},
 {id:'exit',x:11,y:10,name:'Шлюз наружу',type:'ВЫХОД',desc:'Снаружи туман и свобода. Шлюз заперт изнутри.',kind:'exit',blocking:true},
 {id:'guard',x:8,y:9,name:'Сторожевой дрон',type:'УГРОЗА',desc:'Он патрулирует между клумбами. Сенсор реагирует на свет, звук и движение.',kind:'guard',blocking:false,patrol:0}
];
const wallBlocks=[];for(let x=0;x<W;x++){wallBlocks.push({x,y:0},{x,y:H-1})}for(let y=1;y<H-1;y++){wallBlocks.push({x:0,y},{x:W-1,y})}
const blocked=(x,y)=>{if(x<.55||y<.55||x>W-1.55||y>H-1.55)return true;return props.some(p=>p.blocking&&Math.abs(p.x-x)<.62&&Math.abs(p.y-y)<.62)||wallBlocks.some(b=>Math.abs(b.x-x)<.55&&Math.abs(b.y-y)<.55)};
function resize(){cw=innerWidth;ch=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(cw*dpr);canvas.height=Math.floor(ch*dpr);canvas.style.width=cw+'px';canvas.style.height=ch+'px';ctx.setTransform(dpr,0,0,dpr,0,0);tileW=Math.min(cw<760?38:65,cw/(cw<760?10.3:19),ch/(cw<760?7.1:10.2));tileW=Math.max(tileW,18);tileH=tileW*.5}
addEventListener('resize',resize,{passive:true});resize();
const iso=(x,y)=>({x:(x-y)*tileW*.5,y:(x+y)*tileH*.5});
function screen(x,y,z=0){const p=iso(x,y);return{x:p.x-cam.x+cw/2,y:p.y-cam.y+ch*.52-z}}
const polygon=(points,fill,stroke=null,lw=1)=>{ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke()}};
function ellipse(x,y,rx,ry,color,blur=0){ctx.save();if(blur){ctx.shadowColor=color;ctx.shadowBlur=blur}ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,TAU);ctx.fill();ctx.restore()}
function line(x1,y1,x2,y2,color,width=1){ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}
function glow(x,y,r,color){const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,color);g.addColorStop(1,'transparent');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2)}
function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function drawTile(x,y){const p=screen(x,y);const hw=tileW/2,hh=tileH/2;let color=((x*7+y*13)%5===0)?'#182d27':'#142821';if((x+y)%7===0)color='#172b24';polygon([{x:p.x,y:p.y},{x:p.x+hw,y:p.y+hh},{x:p.x,y:p.y+tileH},{x:p.x-hw,y:p.y+hh}],color,'#9cc0a50b',.7);
 if((x*13+y*7)%29===2){line(p.x-4,p.y+hh+2,p.x+3,p.y+hh-1,'#93b09b15',1)}
 if((x+y)%8===1&&x>0&&y>0){ellipse(p.x+((x%3)-1)*5,p.y+hh+2,1.3,1,'#b3c99820')}
}
function drawWall(x,y){const p=screen(x,y),hw=tileW*.5,hh=tileH*.5,h=tileW*.42;polygon([{x:p.x-hw,y:p.y+hh},{x:p.x,y:p.y+tileH},{x:p.x,y:p.y+tileH+h},{x:p.x-hw,y:p.y+hh+h}], '#17241f','#8ba68b18');polygon([{x:p.x,y:p.y+tileH},{x:p.x+hw,y:p.y+hh},{x:p.x+hw,y:p.y+hh+h},{x:p.x,y:p.y+tileH+h}], '#0d1a17','#8ba68b10');polygon([{x:p.x-hw,y:p.y+hh},{x:p.x,y:p.y},{x:p.x+hw,y:p.y+hh},{x:p.x,y:p.y+tileH}], '#26382e','#a6c5a51c');line(p.x-hw,p.y+hh,p.x,y=p.y+tileH,'#b5c5a40d',1)}
function drawProps(p){const s=screen(p.x,p.y),z=tileW;
 if(p.kind==='panel'||p.kind==='terminal'||p.kind==='exit'){
  const isExit=p.kind==='exit',isTerm=p.kind==='terminal';
  ellipse(s.x,s.y+tileH*.43,z*.39,z*.15,'#03080780');
  let ww=z*(isExit?.52:.48),hh=z*.52;rounded(s.x-ww/2,s.y-hh*.48,ww,hh,5,isExit?'#1a2c25':'#24352e','#8198893c');
  rounded(s.x-ww*.38,s.y-hh*.36,ww*.76,hh*.55,3,isExit?'#10211b':(isTerm?'#23443b':'#1b3930'),'#a5c6a834');
  if(isExit){line(s.x-ww*.29,s.y-hh*.32,s.x-ww*.29,s.y+hh*.12,'#76907d66',1.5);line(s.x+ww*.29,s.y-hh*.32,s.x+ww*.29,s.y+hh*.12,'#76907d66',1.5);ellipse(s.x+ww*.3,s.y-hh*.03,2,2,state.core?'#c8f17b':'#de9d63',5)}
  else{rounded(s.x-ww*.28,s.y-hh*.3,ww*.56,hh*.31,2,state.power?(state.terminal?'#88c479':'#76b28a'):'#4c5043');line(s.x-ww*.2,s.y+hh*.03,s.x+ww*.19,s.y+hh*.03,'#d7f0c65c',1);ellipse(s.x+ww*.3,s.y-hh*.38,2,2,state.power?'#c8f17b':'#d26359',7)}
  if(isTerm&&state.terminal)glow(s.x,s.y-hh*.2,z*.45,'#70d78d20');
 }else if(p.kind==='core'){
  ellipse(s.x,s.y+tileH*.45,z*.31,z*.13,'#030807a0');
  rounded(s.x-z*.22,s.y-z*.52,z*.44,z*.48,5,'#182822','#94b6a346');
  rounded(s.x-z*.14,s.y-z*.47,z*.28,z*.32,7,'#89b98926','#d6e5c747');
  ellipse(s.x,s.y-z*.31,z*.075,z*.08,state.core?'#60715d':'#c8f17b',10);
  if(!state.core)glow(s.x,s.y-z*.3,z*.55,'#8bd47831');
 }else if(p.kind==='plant'){
  ellipse(s.x,s.y+tileH*.35,z*.3,z*.12,'#03080780');
  for(let i=0;i<5;i++){let a=i*TAU/5;let ex=s.x+Math.cos(a)*z*.18,ey=s.y-z*.14+Math.sin(a)*z*.12;ctx.save();ctx.translate(ex,ey);ctx.rotate(a*.28);ellipse(0,0,z*.08,z*.19,'#3f7a58');ellipse(0,-z*.11,z*.045,z*.12,'#77b979');ctx.restore()}
  ellipse(s.x,s.y-z*.18,z*.095,z*.095,'#d5eaa1',12);ellipse(s.x,s.y-z*.18,z*.04,z*.04,'#f3edc3',4);
 }else if(p.kind==='crate'){
  const lifted=state.crateMoved?z*.28:0;
  polygon([{x:s.x-z*.28,y:s.y-z*.2-lifted},{x:s.x,y:s.y-z*.34-lifted},{x:s.x+z*.28,y:s.y-z*.2-lifted},{x:s.x,y:s.y-z*.06-lifted}], '#806648','#d0b18137');
  polygon([{x:s.x-z*.28,y:s.y-z*.2-lifted},{x:s.x,y:s.y-z*.06-lifted},{x:s.x,y:s.y+z*.22-lifted},{x:s.x-z*.28,y:s.y+z*.06-lifted}], '#493d2d','#c9a87726');
  polygon([{x:s.x,y:s.y-z*.06-lifted},{x:s.x+z*.28,y:s.y-z*.2-lifted},{x:s.x+z*.28,y:s.y+z*.06-lifted},{x:s.x,y:s.y+z*.22-lifted}], '#65523a','#c9a87726');
  line(s.x-z*.2,s.y-z*.09-lifted,s.x-z*.2,s.y+z*.09-lifted,'#d3b98444',2);line(s.x+z*.2,s.y-z*.11-lifted,s.x+z*.2,s.y+z*.09-lifted,'#d3b98444',2);
 }else if(p.kind==='locker'){
